{"results": [{"id": "FAM:SF-APPS-049", "label": "Study family SF-APPS-049: 52-series sequential adaptation: durable pivot branches and net swing", "score": 1.449, "reached_via": ["FAM:SF-APPS-075 auto_related_family (record_link_related_to) FAM:SF-APPS-049"], "attributes": {"observed_research_question": "52-series sequential adaptation: durable pivot branches and net swing", "auto_outcome_status": "rejected", "observed_hypothesis": "If-X-fails-then-Y pivot branches and PT net-swing (own PPP - opp next PPP) are durable across ~104 playoff team-offense units.", "observed_result": "durable_branches=[]. Median net swing: CUT +0.36 (neg in 9%), TRANSITION +0.26 (21%), PULL_UP +0.09 (33%), PNR +0.04 (45%), SPOT_UP +0.02 (40%), POST_UP -0.22 (77%), DRIVE -0.27 (88%). n_units: CUT 103, DRIVE/POST_UP/SPO [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "No conditional pivot branch met the durability bar (empty durable_branches). DRIVE/POST_UP negative net swing is the durable aftershock finding, recorded here as the positive half of the same run.", "observed_sample_and_power": "52 series, 104 units"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-011"}]}, {"id": "FAM:SF-APPS-075", "label": "Study family SF-APPS-075: Extended Possession Value (direct PPP + opponent T+1 suppression)", "score": 1.177, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPS-075 (0.82)"], "attributes": {"observed_research_question": "Extended Possession Value (direct PPP + opponent T+1 suppression)", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Play types and players have a real downstream (opponent next-PPP) component beyond direct PPP.", "observed_result": "4/8 PTs downstream real: CUT Ext 1.658 (supp +0.0220), TRANSITION 1.509 (+0.0145), SPOT_UP 1.303 (+0.0124), POST_UP 1.127 (+0.0194). DRIVE downstream not real (opp ATT +0.0024).